const fs = require("fs");
const path = require("path");
const nm = "/w/node_modules";
let pkg;
try {
  pkg = JSON.parse(fs.readFileSync(path.join(nm, "agents", "package.json"), "utf8"));
} catch (e) {
  console.error("ERROR: agents is not installed: " + e.message);
  process.exit(2);
}
if (fs.existsSync(path.join(nm, "@cloudflare", "codemode", "package.json"))) {
  console.error("FAIL: installing agents alone also installed @cloudflare/codemode transitively");
  process.exit(1);
}
console.log("OK: installing agents " + pkg.version + " alone did not install @cloudflare/codemode");
process.exit(0);

